from functools import cmp_to_key


def _parse(version):
    core, _, build = version.partition("+")
    main, sep, pre = core.partition("-")
    major, minor, patch = (int(part) for part in main.split("."))
    prerelease = pre.split(".") if sep else []
    return major, minor, patch, prerelease


def _compare_prerelease(a, b):
    if not a and not b:
        return 0
    if not a:
        return 1
    if not b:
        return -1

    for left, right in zip(a, b):
        left_numeric = left.isdigit()
        right_numeric = right.isdigit()

        if left_numeric and right_numeric:
            left_value, right_value = int(left), int(right)
            if left_value != right_value:
                return -1 if left_value < right_value else 1
        elif left_numeric != right_numeric:
            return -1 if left_numeric else 1
        elif left != right:
            return -1 if left < right else 1

    if len(a) == len(b):
        return 0
    return -1 if len(a) < len(b) else 1


def _compare_versions(a, b):
    a_major, a_minor, a_patch, a_pre = _parse(a)
    b_major, b_minor, b_patch, b_pre = _parse(b)

    for left, right in (
        (a_major, b_major),
        (a_minor, b_minor),
        (a_patch, b_patch),
    ):
        if left != right:
            return -1 if left < right else 1

    return _compare_prerelease(a_pre, b_pre)


def sort_versions(vs):
    return sorted(vs, key=cmp_to_key(_compare_versions))
